{
  "segment_function": "Examines the relationship between labor, the biological life process, and the cyclical nature of nature versus the linear, world-building nature of human life, action, and speech.",
  "claims": [
    {
      "claim": "The least durable tangible things are those required for the life process, which are consumed by use or decay rapidly and return to the natural process.",
      "claim_type": "author_position",
      "supporting_excerpt": "The least durable of tangible things are those needed for the life process itself. Their consumption barely survives the act of their production; in the words of Locke, all those “good things” which are “really useful to the life of man,” to the “necessity of subsisting,” are “generally of short duration, such as—if they are not consumed by use—will decay and perish by themselves.”",
      "support_kind": "direct",
      "confidence": 1
    },
    {
      "claim": "Laboring activities are endlessly repetitive and bound to the recurring cycles of the biological life process, unlike working, which concludes when an object is finished.",
      "claim_type": "author_position",
      "supporting_excerpt": "all human activities which arise out of the necessity to cope with them are bound to the recurring cycles of nature and have in themselves no beginning and no end, properly speaking; unlike working , whose end has come when the object is finished, ready to be added to the common world of things, laboring always moves in the same circle, which is prescribed by the biological process of the living organism and the end of its “toil and trouble” comes only with the death of this organism.",
      "support_kind": "direct",
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "bios",
      "definition": "Specifically human life whose time interval between birth and death is full of events that can be told as a story and establish a biography."
    },
    {
      "term": "zōē",
      "definition": "Mere biological life shared with other living things, retaining the cyclical movement of nature."
    }
  ],
  "distinctions": [
    {
      "item_a": "bios",
      "item_b": "zōē",
      "distinction": "Bios is specifically human life constituting worldly events that can be told as a story and established as a biography, whereas zōē is mere biological life shared with other living things that forever retains nature's cyclical movement."
    },
    {
      "item_a": "laboring",
      "item_b": "working",
      "distinction": "Laboring always moves in the same circle prescribed by the biological process of the living organism without a proper beginning or end, whereas working comes to an end when its object is finished and added to the common world of things."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "Distinction between bios and zōē",
    "Cyclical nature of biological life and labor versus linear nature of human life, action, and speech"
  ]
}

